SOURCE_KEYS = ('src', 'ref', 'title', 'site', 'url', 'shelf', 'doc_id', 'section', 'page', 'at', 'what')   # what a slide keeps of the source of its passage

def _source(r:dict) -> dict:
    """`{'src': ...}`: where the passage of `r` comes from (its kind, title, document, place, site and link), so the slide can name it
    (`slide_source`); `{}` with no passage. A passage of a document in your vault has the kind `doc`."""
    return dict(src={k: v for k in SOURCE_KEYS if (v := r.get(k) if k != 'src' else r.get(k) or 'doc') not in (None, '')}) if r.get('text') else {}

def slide_source(s:dict) -> AttrDict|None:
    "The `source_of` the passage of slide `s`, or None. A talk made before 0.0.13 kept a source only for a passage from the web, with no kind."
    sh = s.get('show') or {}
    if not (src := sh.get('src')) or not (sh.get('passage') or '').strip(): return None
    return source_of({'src': 'web', **src, 'text': sh['passage']})

def _idea(lr:Learning, ask, i:int, s:dict, sid:str, choice:bool, no_code:bool=False) -> dict:
    """The `idea` slide `sid` of walk step `i`. A section of a notebook goes to the slide writer in `_read`, and the slide shows only its `code_piece`
    (none with `no_code`). With `no_code`, another passage with code also goes to `_read`, not to the room."""
    r = s.get('read') or {}
    text, fig = r.get('text') or '', r.get('figure')
    demo, a = _idea_ask(lr, ask, s, text, choice, no_code)
    nb = bool(r.get('cells')) and bool(text.strip())
    read = text if nb or (no_code and '```' in text) else ''
    passage = ('' if no_code else code_piece(text)) if nb else '' if read else text
    show = dict(passage=passage, figure=f'asset:{fig}' if fig else None, demo=demo, **(_source(r) if passage else {}))
    beats = [b for b in ('passage', 'figure', 'demo') if show[b]]
    c = lr.concept(s['slug']) or {}
    return dict(id=sid, kind='idea', step=i, concept=s['slug'], title=c.get('name') or s['slug'], section=r.get('section') or '',
                show=show, beats=beats, notes=s.get('note') or '', ask=a, mins=slide_minutes(shown_step(s, passage) if read or hands_on(s) else s, a), **({'_read': read} if read else {}))

def hands_on(s:dict) -> bool:
    "Whether the check of walk step `s` is hands-on work (a notebook or code), which a room does not do during a talk: its slide asks a question in its place."
    return (s.get('check') or {}).get('kind') in ('notebook', 'code')

def shown_step(s:dict, passage:str) -> dict:
    "Step `s` as its slide shows it, for its minutes: a slide that explains a section of a notebook shows only `passage` and has a question, not the hands-on check of the walk."
    return {**s, 'read': {'text': passage}, 'check': {'kind': 'short'}}

def _unread(s:dict) -> dict:
    "Slide `s` with no `_read`: that text is for the slide writer only, and the talk does not keep it."
    return {k: v for k, v in s.items() if k != '_read'}

