def _tmeta(r): return AttrDict({**meta_of(r), 'doc_id': r['id']})

@patch
def put_talk(self:Learning, t:dict) -> AttrDict:
    "Save talk `t`, and replace an earlier one with the same id. A talk with problems raises `ValueError`."
    t = {k: v for k, v in dict(t).items() if k != 'doc_id'}
    if (ps := check_talk(t)): raise ValueError('; '.join(ps))
    t['updated'] = time.time()
    text = f"Talk: {t['title']} ({t['id']})\n\nSlides: {', '.join(s.get('title') or '' for s in t['slides'])}"
    r = self.v.put(text, title=f"Talk: {t['title']}", source=_src('talk', t['id']), kind='talk', meta=t)
    return self.talk(t['id'])

# %% ../nbs/05_show.ipynb #347943e7
def _old_sources(lr:Learning, t:AttrDict) -> AttrDict:
    """Talk `t` with a source on each slide that shows a passage but keeps no source: a talk made before 0.0.13 kept one only for a
    passage from the web. The source comes from the walk step of the slide, when the walk still has that step; else it is your source
    with the title of the walk. Nothing is saved here."""
    w = None
    for s in t.get('slides') or []:
        sh = s.get('show') or {}
        if sh.get('src') or not (sh.get('passage') or '').strip(): continue
        if w is None: w = lr.journey((t.get('src') or {}).get('walk') or '') or {}
        ss, k = w.get('steps') or [], s.get('step')
        r = (ss[k].get('read') or {}) if isinstance(k, int) and 0 <= k < len(ss) and ss[k].get('slug') == s.get('concept') else {}
        sh['src'] = _source(r)['src'] if r.get('text') else dict(src='doc', title=w.get('title') or t.get('title') or 'your text')
    return t

def code_cols(s:dict) -> int:
    "The longest line of code that slide `s` has room for: `CODE_COLS` beside its points, a figure or a demo, else `CODE_COLS_ALONE`."
    sh = s.get('show') or {}
    return CODE_COLS if sh.get('body') or sh.get('figure') or sh.get('demo') else CODE_COLS_ALONE

_FENCE = re.compile(r'```[\w-]*\n(.*?)\n```', re.S)

def code_wide(passage, cols:int) -> bool:
    "Whether a code fence in `passage` has a line longer than `cols` characters."
    return any(len(l) > cols for code in _FENCE.findall(passage or '') for l in code.splitlines())

def _fit_code(lr:Learning, t:AttrDict) -> AttrDict:
    """Talk `t` with no code that is too wide for its slide (`code_wide`): a talk made before 0.0.19 can keep long lines. Each code fence that is too
    wide gives its place to a shorter code piece from the section of the walk step (`code_piece`), or goes. A slide with only that code then shows
    its points; a slide with no points keeps its code. Nothing is saved here."""
    w = None
    for s in t.get('slides') or []:
        sh = s.get('show') or {}
        if s.get('kind') != 'idea' or not code_wide(sh.get('passage'), cols := code_cols(s)): continue
        if w is None: w = lr.journey((t.get('src') or {}).get('walk') or '') or {}
        ss, k = w.get('steps') or [], s.get('step')
        r = (ss[k].get('read') or {}) if isinstance(k, int) and 0 <= k < len(ss) and ss[k].get('slug') == s.get('concept') else {}
        piece = [code_piece(r.get('text') or '', cols)]   # the shorter piece takes the place of the first wide fence only
        p = re.sub(r'\n{3,}', '\n\n', _FENCE.sub(lambda m: (piece.pop() if piece else '') if code_wide(m[0], cols) else m[0], sh['passage'])).strip()
        if p: sh['passage'] = p
        elif sh.get('body'): sh['passage'] = ''; s['beats'] = [b for b in s.get('beats') or [] if b != 'passage']
    return t

@patch
def talk(self:Learning, tid:str) -> AttrDict|None:
    "One talk by id. A slide of an old talk gets the source of its passage (`_old_sources`), and code that fits the slide (`_fit_code`)."
    r = self.v.by_source(_src('talk', tid))
    return _fit_code(self, _old_sources(self, _tmeta(r))) if r else None

@patch
def talks(self:Learning) -> L:
    "All talks, the most recently changed first."
    return L(sorted(map(_tmeta, self._docs('talk')), key=lambda t: -t.get('updated', 0)))

@patch
def drop_talk(self:Learning, tid:str):
    "Delete talk `tid` with its runs, its history of changes, the side walks that it opened beside its slides, and its hidden walk (`walk_for_talk`). A walk of your own stays."
    t = self.talk(tid)
    w = self.journey(((t or {}).get('src') or {}).get('walk') or '') or {}
    p = w.get('parent') or {}
    gone, todo = set(), [j.id for j in self.journeys() if ((j.get('parent') or {}).get('talk')) == tid] + ([w['id']] if p.get('for') == 'talk' and not p.get('journey') else [])
    while todo:
        if (k := todo.pop()) in gone: continue
        gone.add(k)
        todo += [j.id for j in self.journeys() if (j.get('parent') or {}).get('walk') == k]
    for k in gone: self.drop_edits('walk', k); self.drop_journey(k)
    for r in self.runs(tid): self.v.forget(r.doc_id)
    self.drop_edits('talk', tid)
    if t: self.v.forget(t.doc_id)

