ROLES = ('main', 'extra', 'dropped')   # the role of a source in a brief

def new_brief(**kw) -> dict:
    "A brief with no sources. Research is on when the `research.on` setting is on."
    return {**dict(kind='', goal='', sources=[], rules='', research=bool(val('research.on')), aim='', audience='', no_code=False, minutes=0, keep=[]), **kw}

def brief_chips(b:dict) -> list:
    "The chip ids of the sources of brief `b` that are not dropped: the main sources first, then the extra sources."
    ss = b.get('sources') or []
    return [s['id'] for r in ROLES[:2] for s in ss if s.get('role') == r]

# %% ../nbs/05_show.ipynb #1d8d4ce8
_SHAPE = re.compile(r'\b(polls?|(first|last|opening|closing|final|end) slides?|start (with|by)|end (with|by)|open the notebook|into the notebook|\d+[- ]minutes?|minutes? (long|slot)|'
                    r'\d+ slides|(more|fewer|less) slides|number of slides|order of the (slides|ideas))\b', re.I)   # a rule about the shape of the talk
_WORDING = re.compile(r'\b(language|wording|style|tone|english|grade \d+|asd-?ste|keep (the|all|every|each) (content|ideas|facts|examples))\b', re.I)   # a rule about the words: never a shape rule

def is_shape(x:str) -> bool:
    "Whether sentence `x` is a rule about the shape of the whole talk (a poll, the first or last slide, the minutes, the count of slides), and not about its words."
    return bool(_SHAPE.search(x)) and not _WORDING.search(x)

def shape_split(t:str) -> tuple:
    "The sentences of `t` as two texts: the ones that are not about the shape of the whole talk (a poll, the first or last slide, the minutes), and the ones that are."
    ss = [x for x in re.split(r'(?<=[.!?])\s+', ' '.join(str(t or '').split())) if x]
    return ' '.join(x for x in ss if not is_shape(x)), ' '.join(x for x in ss if is_shape(x))

def shape_free(t:str) -> str:
    "The sentences of `t` that are not about the shape of the whole talk: what the writer of one slide gets."
    return shape_split(t)[0]

def brief_asks(b:dict, slides:bool=False) -> str:
    """What brief `b` asks of the planner and the slide writer: the roles of the sources, the rules, the aim and research off. '' when it asks nothing.
    With `slides`, for the writer of one slide: a rule about the shape of the whole talk (a poll, the first or last slide, the minutes) is left out,
    so it does not turn into a point on each slide."""
    ss = b.get('sources') or []
    names = lambda r: ', '.join(s.get('name') or s['id'] for s in ss if s.get('role') == r)
    out = []
    if (m := names('main')) and (x := names('extra')): out.append(f'The main source is {m}. The extra sources ({x}) only add to it. Where they conflict, use the main source.')
    if (r := ' '.join(str(b.get('rules') or '').split())):
        if slides: r = shape_free(r)
        if r: out.append(r if r.endswith('.') else r + '.')
    if (a := ' '.join(str(b.get('aim') or '').split())) and slides: a = shape_free(a)   # a shape rule in the aim stays out of each slide too
    if a: out.append(f'The aim: {a}' + ('' if a.endswith('.') else '.'))
    if ss and not b.get('research', True): out.append('Use only these sources.')
    return ' '.join(out)

